$servername = 'localhost';
$username = 'username';
$password = 'password';
$DB_Name = 'school_DB';
$conn = mysqli_connect($servername, $username, $password, $DB_Name);
if (!$conn) {
    die('Connection failed: ' . mysqli_connect_error());
}
echo 'Connected successfully';

1. mysqli_connect(): MySQL தரவுதளத்துடன் இணைக்க பயன்படுகிறது. நான்கு அளபுருக்கள் தேவை: சேவையக பெயர், பயனர் பெயர், கடவுச்சொல், தரவுதள பெயர்.
mysqli_connect('localhost', 'username', 'password', 'DB_Name');

2. mysqli_query(): இணைக்கப்பட்ட தரவுதளத்தில் SQL வினவலை இயக்க பயன்படுகிறது. இரண்டு அளபுருக்கள் தேவை: இணைப்புப் பொருள், SQL வினவல்.
mysqli_query($conn, 'SELECT * FROM student');

3. mysqli_close(): தரவுதள இணைப்பை மூட பயன்படுகிறது. ஒரே ஒரு அளபுரு தேவை: இணைப்புப் பொருள்.
mysqli_close($conn);

இம்மூன்று செயற்கூறுகளும் இணைந்து PHP-MySQL தொடர்பின் அடிப்படை வாழ்க்கைச் சுழற்சியை (இணைத்தல் → வினவுதல் → மூடுதல்) நிறைவேற்றுகின்றன.

MySQL வினவல் என்பது தரவுதளத்திடம் தரவைப் பெறவோ, மாற்றவோ கோரும் SQL கூற்று ஆகும். PHP-இல் mysqli_query() செயற்கூறு மூலம் இதை இயக்கலாம்.

முழுமையான எடுத்துக்காட்டு:
<?php
$servername='localhost';
$username='username';
$password='password';
$dbname='school_DB';
$connection = mysqli_connect($servername,$username,$password,$dbname);

if(mysqli_connect_errno()) {
    echo 'Failed to connect to MySQL: ' . mysqli_connect_error();
}

$sql_stmt='SELECT * FROM my_contacts';
$result=mysqli_query($connection,$sql_stmt);
$rows=mysqli_num_rows($result);

if($rows){
    while($row=mysqli_fetch_array($result)){
        echo 'ID: '.$row['id'].'<br>';
        echo 'Email: '.$row['email'].'<br>';
    }
}
mysqli_close($connection);
?>

இந்த நிரல் தரவுதளத்துடன் இணைந்து, 'my_contacts' அட்டவணையின் அனைத்து பதிவுகளையும் பெற்று, ஒவ்வொரு பதிவின் ID மற்றும் Email மதிப்புகளையும் திரையில் காட்டி, இறுதியில் இணைப்பை மூடுகிறது.
